let programShells=[],shellScope='';
const beforeProgramStudio=render;
render=function(){const route=location.hash.slice(1);if(!['program-studio','agentic-catalog'].includes(route))return beforeProgramStudio();const publicView=route==='agentic-catalog';document.getElementById('app').innerHTML=integratedShell(route,heading(publicView?'Agentic AI courses & certificates':'Program design studio',publicView?'Scholarion Academy · Publication-approved offerings':'Programs #1–#26 · Instructor draft workspace')+(publicView?`<section class="card prose"><h2>No approved offerings are open for enrollment</h2><p>Draft programs are excluded from this public catalog. Academic publication and checkout remain disabled.</p><a href="#catalog">Explore clearly labeled catalog previews</a> · <a href="#self-paced">Self-paced draft previews</a> · <a href="#help">Talk to an advisor through local Support</a><h2>Learning and credentials</h2><p>Proposed tracks cover AI foundations, retrieval, agents, evaluation and responsible deployment. Certificates recognize completion; no accreditation, employment outcome or independent professional certification is claimed.</p></section>`:`<section class="card prose"><p id="shell-status" role="status">Connecting…</p><label>Authorized course context<select id="shell-scope"></select></label><button class="button" id="shell-load">Load all program draft shells</button><p>Idempotent loading preserves existing revisions. These are design shells, not published LMS courses or enrollment grants.</p><a href="#curriculum-commons">Versioned shared modules</a> · <a href="#consolidation">Consolidation register</a> · <a href="#agentic-catalog">Public catalog</a></section><div id="shell-cards"></div><div id="shell-detail"></div>`),model.role);bind();normalizeWorkspace();if(!publicView)loadProgramShells();};
async function loadProgramShells(){try{workspaceSession=await workspaceApi('session');if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';shellScope=selectedCourse;const d=await workspaceApi('program-shells/list');if(location.hash!=='#program-studio')return;programShells=d.shells;normalizeWorkspace();document.getElementById('shell-scope').innerHTML=workspaceSession.courses.map(c=>`<option ${c===selectedCourse?'selected':''}>${esc(c)}</option>`).join('');document.getElementById('shell-status').textContent=d.shells.length+' saved draft shells. Publication is blocked pending academic release requirements.';document.getElementById('shell-cards').innerHTML=`<div class="catalog-grid">${d.shells.map(p=>`<article class="card prose"><p>#${p.program} · Revision ${p.revision} · Draft</p><h2>${esc(p.title)}</h2><p>${p.totalWeeks||10}-week program design · ${p.competencies.length} competencies · ${p.courses?p.courses.length:1} course block(s)</p><button class="button secondary" data-shell-open="${p.program}">Review shell</button></article>`).join('')}</div>`;}catch(e){if(location.hash==='#program-studio')document.getElementById('shell-status').textContent=e.message+' — Connect with an authorized instructor identity.';}}
function openProgramShell(n){const p=programShells.find(p=>p.program===n);document.getElementById('shell-detail').innerHTML=`<section class="card prose"><h2>${esc(p.title)}</h2><p>Lead faculty: ${esc(p.faculty)}</p><p>${esc(p.dependencyNotes)}</p><h3>Competencies</h3><ul>${p.competencies.map(c=>`<li>${esc(c.id)}: ${esc(c.text)}</li>`).join('')}</ul><h3>Weekly design</h3>${(p.courses?p.courses.flatMap(c=>c.modules.map(m=>({...m,title:c.title+' / '+m.title}))):p.modules).map(m=>`<details><summary>Week ${m.week}: ${esc(m.title)}</summary><ul>${m.outcomes.map(o=>`<li>${esc(o.id)} → ${esc(o.competency)}: ${esc(o.text)}</li>`).join('')}</ul><p>Student activity: ${esc(m.activity.student)}</p><p>Instructor edition: ${esc(m.activity.instructor)}</p></details>`).join('')}${p.courses?'<h3>Assessment plans</h3>'+p.courses.map(c=>'<details><summary>'+esc(c.id)+' assessment inventory</summary><ul>'+(c.assessmentPlan||[]).map(a=>'<li>Week '+a.week+' · '+esc(a.title)+' · '+esc(a.state)+' · '+esc(a.outcomes.join(', '))+'</li>').join('')+'</ul><p>Planned items do not contain validated assessment assets.</p></details>').join(''):''}<h3>Capstone</h3><p>${esc(p.capstone)}</p><ul>${p.rubric.map(r=>`<li>${esc(r.criterion)}: ${r.points} points</li>`).join('')}</ul>${p.program===15?'<a href="#program15-curriculum">Open existing twenty-session intensive design</a>':''}<button class="button secondary" data-shell-audit="${p.program}">Run readiness audit</button><div id="shell-audit-result" role="status"></div><h3>Unmet publication gates</h3><ul>${p.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><form id="shell-save" data-program="${p.program}" data-revision="${p.revision}"><label>Educator review notes<textarea name="notes" maxlength="8000" rows="5">${esc(p.notes)}</textarea></label><button class="button">Save a new review version</button></form><button class="button secondary" data-shell-export="${p.program}">Download draft design package</button><p>Export includes outlines and review notes, not finished course media or verified academic approval.</p></section>`;}
document.addEventListener('change',e=>{if(e.target.id==='shell-scope'){selectedCourse=e.target.value;document.getElementById('shell-detail').innerHTML='';loadProgramShells();}});
document.addEventListener('click',async e=>{const b=e.target.closest('#shell-load,[data-shell-open],[data-shell-export]');if(!b)return;try{if(b.id==='shell-load'){b.disabled=true;await workspaceApi('program-shells/load');await loadProgramShells();}else if(b.dataset.shellOpen)openProgramShell(Number(b.dataset.shellOpen));else{const p={...programShells.find(x=>x.program===Number(b.dataset.shellExport))};const commons=await workspaceApi('commons/list');p.sharedModules=commons.pins.filter(x=>x.program===p.program).map(pin=>({pin,content:commons.modules.find(m=>m.module===pin.module&&m.version===pin.version)}));download('scholarion-program-'+p.program+'-draft.json',JSON.stringify(p,null,2),'application/json');}}catch(err){document.getElementById('shell-status').textContent=err.message;}finally{b.disabled=false;}});
document.addEventListener('submit',async e=>{if(e.target.id!=='shell-save')return;e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const n=Number(e.target.dataset.program);await workspaceApi('program-shells/save',{program:n,revision:Number(e.target.dataset.revision),notes:new FormData(e.target).get('notes'),course:shellScope});await loadProgramShells();openProgramShell(n);}catch(err){document.getElementById('shell-status').textContent=err.message;}finally{b.disabled=false;}});
render();

document.addEventListener('click',async e=>{const b=e.target.closest('[data-shell-audit]');if(!b)return;b.disabled=true;try{const d=await workspaceApi('program-shells/audit',{program:Number(b.dataset.shellAudit)});document.getElementById('shell-audit-result').innerHTML='<h3>Publication blocked</h3><p>'+esc(d.note)+'</p>'+d.courses.map(c=>'<details><summary>'+esc(c.course)+' · '+c.plannedAssessments+' planned assessments · '+c.gaps.length+' gaps</summary><ul>'+c.gaps.map(g=>'<li>'+esc(g)+'</li>').join('')+'</ul></details>').join('');}catch(err){document.getElementById('shell-status').textContent=err.message;}finally{b.disabled=false;}});
